UPDATE tb_ai_log_ai_task
SET delivery_status = 'SUCCESS',
    delivery_token = NULL,
    report_object_key = #{objectKey},
    delivery_error_message = NULL,
    delivered_time = #{now},
    update_time = #{now}
WHERE id = #{taskId}
  AND delivery_status = 'DELIVERING'
  AND delivery_token = #{claimToken}

UPDATE tb_ai_log_ai_task
SET delivery_status = 'FAILED',
    delivery_token = NULL,
    report_object_key = COALESCE(#{objectKey}, report_object_key),
    delivery_error_message = #{errorMessage},
    update_time = #{now}
WHERE id = #{taskId}
  AND delivery_status = 'DELIVERING'
  AND delivery_token = #{claimToken}
